package dev.pulsewatch.repo;
import dev.pulsewatch.domain.Alert; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*;
public interface AlertRepository extends JpaRepository<Alert,UUID> { boolean existsByServiceIdAndMessageAndStatusIn(UUID serviceId,String message,Collection<Alert.Lifecycle> statuses); List<Alert> findAllByOrderByCreatedAtDesc(); List<Alert> findByServiceIdAndStatusIn(UUID serviceId,Collection<Alert.Lifecycle> statuses); long countByStatusIn(Collection<Alert.Lifecycle> statuses); long countBySeverityAndStatusIn(Alert.Severity severity,Collection<Alert.Lifecycle> statuses); Optional<Alert> findFirstByServiceIdAndMessageAndStatusInOrderByCreatedAtDesc(UUID serviceId,String message,Collection<Alert.Lifecycle> statuses); }
